327	#[typst_macros::time(name = "handle page")]
328	pub(crate) fn handle_frame(
329	    fc: &mut FrameContext,
330	    frame: &Frame,
331	    padding: Sides<Abs>,
332	    fill: Option<Paint>,
333	    surface: &mut Surface,
334	    gc: &mut GlobalContext,
335	) -> SourceResult<()> {
336	    fc.push();
337	
338	    if frame.kind().is_hard() {
339	        fc.state_mut().register_container(frame.size());
340	    }
341	
342	    if let Some(fill) = fill {
343	        let shape = Geometry::Rect(frame.size() + padding.sum_by_axis()).filled(fill);
344	        handle_shape(
345	            fc,
346	            &shape,
347	            surface,
348	            gc,
349	            Span::detached(),
350	            ArtifactType::Background,
351	        )?;
352	    }
353	
354	    fc.push();
355	    fc.state_mut()
356	        .pre_concat(Transform::translate(padding.left, padding.top));
357	
358	    for (point, item) in frame.items() {
359	        fc.push();
360	        fc.state_mut().pre_concat(Transform::translate(point.x, point.y));
361	
362	        match item {
363	            FrameItem::Group(g) => handle_group(fc, g, surface, gc)?,
364	            FrameItem::Text(t) => handle_text(fc, t, surface, gc)?,
365	            FrameItem::Shape(s, span) => {
366	                handle_shape(fc, s, surface, gc, *span, ArtifactType::Layout)?;
367	            }
368	            FrameItem::Image(image, size, span) => {
369	                handle_image(gc, fc, image, *size, surface, *span)?;
370	            }
371	            FrameItem::Link(dest, size) => handle_link(fc, gc, dest, *size)?,
372	            FrameItem::Tag(Tag::Start(_, flags)) => {
373	                if flags.tagged {
374	                    tags::handle_start(gc, fc, surface);
375	                }
376	            }
377	            FrameItem::Tag(Tag::End(_, _, flags)) => {
378	                if flags.tagged {
379	                    tags::handle_end(gc, fc, surface);
380	                }
381	            }
382	        }
383	
384	        fc.pop();
385	    }
386	
387	    fc.pop();
388	    fc.pop();
389	
390	    Ok(())
391	}
392	
393	pub(crate) fn handle_group(
394	    fc: &mut FrameContext,
395	    group: &GroupItem,
396	    surface: &mut Surface,
397	    gc: &mut GlobalContext,
398	) -> SourceResult<()> {
399	    fc.push();
400	    fc.state_mut().pre_concat(group.transform);
401	
402	    tags::group(gc, fc, surface, group.parent, |gc, fc, surface| {
403	        let clip_path = group
404	            .clip
405	            .as_ref()
406	            .and_then(|p| {
407	                let mut builder = PathBuilder::new();
408	                convert_path(p, &mut builder);
409	                builder.finish()
410	            })
411	            .and_then(|p| p.transform(fc.state().transform.to_krilla()));
412	
413	        if let Some(clip_path) = &clip_path {
414	            surface.push_clip_path(clip_path, &krilla::paint::FillRule::NonZero);
415	        }
416	
417	        let res =
418	            handle_frame(fc, &group.frame, Sides::splat(Abs::zero()), None, surface, gc);
419	
420	        if clip_path.is_some() {
421	            surface.pop();
422	        }
423	
424	        res
425	    })?;
426	
427	    fc.pop();
428	
429	    Ok(())
430	}
